import java.lang.classfile.*; import java.lang.classfile.attribute.*; import java.lang.constant.*; import java.nio.file.*; import java.util.*; import static java.lang.classfile.ClassFile.*;
public class Generate { public static void main(String[] args)throws Exception {String[] names={"AotNonfinal","AotFinal","AotOrdinary","AotOrdinaryFinal"}; for(int i=0;i<4;i++){ClassDesc p=ClassDesc.of("probe."+names[i]); final int j=i; byte[] bytes=ClassFile.of().build(p,b->{b.withFlags(ACC_PUBLIC|ACC_SUPER|((j%2==1)?ACC_FINAL:0)); if(j<2)b.with(InnerClassesAttribute.of(InnerClassInfo.of(p,Optional.of(ClassDesc.of("probe.Outer")),Optional.of(names[j]),ACC_PUBLIC|((j==0)?ACC_FINAL:0))));}); Path out=Path.of(args[0],"probe",names[i]+".class");Files.createDirectories(out.getParent());Files.write(out,bytes);}}}
